import {normalizeLabSite} from './lab-site-management.js';
import {mergeEquipmentSite,EQUIPMENT_IMAGES} from './equipment-site-content.js';
import {isProductionShop} from './frame-production.js';
export async function getEquipmentSiteState(pool,shop){const row=(await pool.query('SELECT config,revision FROM equipment_public_site_content WHERE shop_id=$1',[shop.id])).rows[0];const publicShop=Object.fromEntries(['id','name','description','phone','address','province','city','business_category','sale_enabled','rental_enabled'].map(k=>[k,shop[k]]));return {shop:publicShop,config:mergeEquipmentSite(shop,row?.config||{}),revision:row?.revision||0,defaultImages:EQUIPMENT_IMAGES};}
export async function handleEquipmentSiteManagement(req,res,url,actor,d){if(url.pathname!=='/api/rental/site')return false;const reply=(s,b)=>{d.sendJson(res,s,b);return true;};if(actor?.rentalRole!=='shop_admin')return reply(403,{error:'forbidden'});const shop=await d.currentShop(actor);if(!shop||isProductionShop(shop))return reply(403,{error:'forbidden'});try{if(req.method==='GET')return reply(200,{...await getEquipmentSiteState(d.pool,shop),domains:(await d.pool.query('SELECT hostname,active FROM equipment_store_domains WHERE shop_id=$1 AND released_at IS NULL ORDER BY created_at',[shop.id])).rows});if(req.method==='PUT'){if(req.headers.origin!==d.publicOrigin)return reply(403,{error:'invalid_origin'});const b=await d.bodyJson(req,3500000);if(!b||!Number.isInteger(b.revision)||b.revision<0)return reply(400,{error:'invalid_site_revision'});const current=(await d.pool.query('SELECT revision FROM equipment_public_site_content WHERE shop_id=$1',[shop.id])).rows[0];if(!current&&b.revision!==0)return reply(409,{error:'site_revision_conflict'});const config=await normalizeLabSite(b.config,d.sharp,EQUIPMENT_IMAGES),row=(await d.pool.query(`INSERT INTO equipment_public_site_content(shop_id,config,updated_by,revision) VALUES($1,$2::jsonb,$3,1) ON CONFLICT(shop_id) DO UPDATE SET config=EXCLUDED.config,updated_by=EXCLUDED.updated_by,revision=equipment_public_site_content.revision+1,updated_at=now() WHERE equipment_public_site_content.revision=$4 RETURNING config,revision`,[shop.id,JSON.stringify(config),actor.userId,b.revision])).rows[0];if(!row)return reply(409,{error:'site_revision_conflict'});await d.audit(actor.userId,undefined,'equipment_site.update','equipment_rental_shop',shop.id,{revision:row.revision});return reply(200,{revision:row.revision,config:mergeEquipmentSite(shop,row.config)});}return reply(405,{error:'method_not_allowed'});}catch(e){if(e.status)return reply(e.status,{error:e.message});throw e;}}
